55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const BLOCK_SIZE = 3;
68	const BLOCK_BASE_PREMIUM = 60;
69	
70	const groupBasePremium = (type: string, count: number): number => {
71	  if (count === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
72	  return count * BASE_PREMIUMS[type];
73	};
74	
75	const countByType = (items: Item[]): Map<string, number> => {
76	  const counts = new Map<string, number>();
77	  for (const item of items) {
78	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
79	  }
80	  return counts;
81	};
82	
83	const quotePremium = (items: Item[]): number => {
84	  let policyBase = 0;
85	  for (const [type, count] of countByType(items)) {
86	    policyBase += groupBasePremium(type, count);
87	  }
88	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
89	  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
90	};
91	
92	const runStep = (step: Step): StepResult => ({
93	  premium: quotePremium((step as QuoteStep).items),
94	});
95	
96	export const runScenario = (scenario: Scenario): ScenarioResult => ({
97	  results: scenario.steps.map(runStep),
98	});
